constraints:
1 ≤ N ≤ 10^{6}
0 ≤ A_{i} ≤ 10^{18}

expected time complexity: O(N)
expected auxiliary space: O(N)

standard_solution_code:
class Solution:

	def nextLargerElement(self, arr, n):
		list1 = [-1] * n
		stack = []
		for i in range(n):
			while stack and arr[i] > arr[stack[-1]]:
				index = stack.pop()
				list1[index] = arr[i]
			stack.append(i)
		return list1
